import 'package:flutter/material.dart'; import 'package:share_plus/share_plus.dart'; import 'table_screen.dart';
class LobbyScreen extends StatefulWidget { const LobbyScreen({super.key}); @override State<LobbyScreen> createState()=>_LobbyScreenState(); }
class _LobbyScreenState extends State<LobbyScreen>{ final players=['أنت','Bot 1']; String difficulty='عادي'; @override Widget build(BuildContext context)=>Directionality(textDirection:TextDirection.rtl,child:Scaffold(appBar:AppBar(title:const Text('غرفة خاصة')),body:Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Card(child:ListTile(title:const Text('رمز الغرفة',style:TextStyle(fontWeight:FontWeight.bold)),subtitle:const Text('ABCD',style:TextStyle(fontSize:28,letterSpacing:6)),trailing:IconButton(icon:const Icon(Icons.share),onPressed:()=>Share.share('انضم إلى غرفة ضعيف جدا: ABCD')))),const SizedBox(height:16),const Text('اللاعبون',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),...players.map((p)=>Card(child:ListTile(leading:CircleAvatar(child:Text(p[0])),title:Text(p),trailing:p=='أنت'?const Text('المضيف'):IconButton(icon:const Icon(Icons.close),onPressed:()=>setState(()=>players.remove(p))))),OutlinedButton.icon(onPressed:players.length<4?()=>setState(()=>players.add('Bot ${players.length}')):null,icon:const Icon(Icons.add),label:const Text('إضافة بوت')),DropdownButtonFormField(value:difficulty,items:['سهل','عادي','صعب','خبير'].map((x)=>DropdownMenuItem(value:x,child:Text('صعوبة البوت: $x'))).toList(),onChanged:(v)=>setState(()=>difficulty=v!)),const Spacer(),FilledButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const TableScreen())),child:const Padding(padding:EdgeInsets.all(14),child:Text('ابدأ اللعبة')))])));
}
